import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Entrances and Experience","description":"How Hearth turns web, command line, mobile, messaging, task cards, approvals, artifacts, and takeover into one attention interface.","frontmatter":{"title":"Entrances and Experience","description":"How Hearth turns web, command line, mobile, messaging, task cards, approvals, artifacts, and takeover into one attention interface.","outline":false},"headers":[],"relativePath":"en/design/experience.md","filePath":"en/design/experience.md","lastUpdated":null}'),s={name:"en/design/experience.md"};function i(o,e,d,c,h,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="entrances-and-experience" tabindex="-1">Entrances and Experience <a class="header-anchor" href="#entrances-and-experience" aria-label="Permalink to &quot;Entrances and Experience&quot;">​</a></h1><p class="lead">Hearth is not an endless chat window. It is an operating surface organized around tasks, approvals, artifacts, and takeover. Users do not need to know which executor is doing the work; they need to see what the system is doing, where their attention is required, and whether the result can be trusted.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><p>The central problem of the entrance is attention, not information volume. When users open Hearth, they should first see running tasks, actions waiting for a decision, recently delivered artifacts, and failures that need recovery, rather than a long transcript.</p><p>Web, command line, phone, and instant messaging can all be entrances, but they share one set of task facts. A user can create a task on a computer, approve it on a phone, and return to the web to inspect the artifact. Devices are different ways to observe and act; they do not produce conflicting states.</p><p>Notifications must be restrained. The system interrupts only when judgment, authorization, or takeover is genuinely needed. Each interruption should explain what happened, the suggested action, and the consequence of ignoring it. Ordinary progress belongs on the task page, not in the user&#39;s attention.</p><p>Mobile prioritizes approvals, artifact review, pause, and takeover; it does not try to reproduce every desktop management feature. The interface must also support keyboard operation, readable contrast, screen reading, and recovery on weak networks, because these capabilities determine whether long-term use is comfortable.</p><h2 id="design-tradeoffs" tabindex="-1">Design Tradeoffs <a class="header-anchor" href="#design-tradeoffs" aria-label="Permalink to &quot;Design Tradeoffs&quot;">​</a></h2><p>Task cards take priority over chat history. Chat is good for expressing intent, but long work needs state, deadlines, artifacts, and recovery. Making chat the only interface forces users to scroll upward and makes it impossible to tell which step truly finished.</p><table tabindex="0"><thead><tr><th>Tradeoff</th><th>Hearth&#39;s choice</th><th>Reason</th></tr></thead><tbody><tr><td>Primary surface</td><td>Task cards, approval cards, and an artifact center</td><td>Users see work status and the next step directly instead of parsing a conversation</td></tr><tr><td>Multiple entrances</td><td>Normalize source, identity, and deduplication</td><td>The same request arriving from email, web, or messaging is handled only once</td></tr><tr><td>State source</td><td>Rebuild the interface from server records</td><td>Refreshes, device changes, and reconnects stay consistent without relying on browser state</td></tr><tr><td>Interruption policy</td><td>Decide by risk and waiting time</td><td>High-risk actions are surfaced quickly while routine progress avoids notification fatigue</td></tr><tr><td>Mobile scope</td><td>Approve, review, take over, and start simple tasks</td><td>Phones suit short actions; complex editing stays on the desktop</td></tr><tr><td>Device capability</td><td>Each device declares its capabilities; do not assume parity</td><td>Some devices can operate desktop software while others can only review and approve</td></tr></tbody></table><p>The interface issues commands; it does not rewrite task facts. When a user clicks Approve, the system must check whether the approval expired, whether parameters changed, and whether the scope is still valid, then write the result and update the interface. Two devices can therefore act at once without showing success while nothing happened.</p><p>When something fails, the interface must be honest: an interrupted connection shows offline, an uncertain result shows verification in progress, and executor failure shows the reason and recoverable actions. The system must not disguise &quot;still trying&quot; as &quot;finished&quot;. When the user takes over, it pauses automatic execution, saves progress, and hands over the operable scope.</p>',12)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
